using System;using System.Linq;using GlassBoard;
class Review {static int Main(){int failures=0;Action<bool,string> check=(ok,name)=>{Console.WriteLine((ok?"PASS: ":"FAIL: ")+name);if(!ok)failures++;};
var p=new Preferences();p.Apps.Add(new Entry{Path="same.exe",Group="A",ExtraGroups=new System.Collections.Generic.List<string>{"B"}});var removal=EntryRules.Remove(p,new[]{"same.exe"},"A");FeatureRules.AddShared(p,new[]{"same.exe"},"C");EntryRules.Undo(p,removal);check(FeatureRules.InGroup(p.Apps[0],"C"),"undo retains group added after removal");
p=new Preferences();p.Apps.Add(new Entry{Path="same.exe",Group="A",ExtraGroups=new System.Collections.Generic.List<string>{"B"}});FeatureRules.Transfer(p,new[]{"same.exe"},"全部","C");check(FeatureRules.InGroup(p.Apps[0],"A")&&FeatureRules.InGroup(p.Apps[0],"B")&&FeatureRules.InGroup(p.Apps[0],"C"),"all-view drop retains existing memberships");
p=new Preferences();p.Apps.Add(new Entry{Path="same.exe",Group=" A ",ExtraGroups=new System.Collections.Generic.List<string>{"A"," B "}});p.Normalize();check(FeatureRules.InGroup(p.Apps[0],"A")&&FeatureRules.Memberships(p.Apps[0]).Count()==2,"legacy whitespace groups normalize without duplicate");
p=new Preferences();p.Apps.Add(new Entry{Path="same.exe",Group="A"});p.Apps.Add(new Entry{Path="SAME.EXE",Group="B",Pinned=true});p.Normalize();check(p.Apps.Count==1&&FeatureRules.InGroup(p.Apps[0],"A")&&FeatureRules.InGroup(p.Apps[0],"B")&&p.Apps[0].Pinned,"duplicate legacy paths merge memberships and pinning");var scheme=FeatureRules.Capture(new Preferences(),"legacy scheme");scheme.Apps.Add(new Entry{Path="same.exe",Group="A"});scheme.Apps.Add(new Entry{Path="SAME.EXE",Group="B",Pinned=true});p=new Preferences();FeatureRules.Apply(p,scheme);check(p.Apps.Count==1&&FeatureRules.InGroup(p.Apps[0],"A")&&FeatureRules.InGroup(p.Apps[0],"B")&&p.Apps[0].Pinned,"legacy appearance scheme merges duplicate memberships");return failures==0?0:1;}}
